head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

// 현재 열려 있는 패널 목록을 한 줄로 출력
scwin.printOpenPanel = function (strPrefix) {
    var arrOpen = $p.getComponentById("target1").getOpenPanelListInfo();
    var arrId = [];
    if (arrOpen) {
        for (var i = 0; i < arrOpen.length; i++) {
            arrId.push(arrOpen[i].id);
        }
    }
    scwin.setReturnValue(strPrefix + " 열린 패널 수 : " + arrId.length + "  열린 패널 : " + (arrId.length > 0 ? arrId.join(", ") : "없음"));
};

// 현재 열린 패널 확인 (openPanel 호출 전 상태 확인용)
scwin.btn_getOpenPanel_onclick = function (e) {
    scwin.printOpenPanel("[현재 상태]");
};

// openPanel('panels2') 호출 (패널 열림/닫힘 동작이 끝난 뒤 확인 버튼으로 상태를 조회한다)
scwin.btn_openPanel_onclick = function (e) {
    $p.getComponentById("target1").openPanel("panels2");
    scwin.setReturnValue("[openPanel('panels2') 호출]");
};
